//! Minimal session lockfile under residual/ — acquire / release / ttl.
use anyhow::{bail, Context, Result};
use std::fs;
use std::path::{Path, PathBuf};
use std::time::{Duration, SystemTime, UNIX_EPOCH};

const LOCK_FILE: &str = ".session.lock";
const DEFAULT_TTL: Duration = Duration::from_secs(300);

pub struct LockGuard {
    path: PathBuf,
}

impl Drop for LockGuard {
    fn drop(&mut self) {
        let _ = fs::remove_file(&self.path);
    }
}

pub fn lock_path(residual_dir: &Path) -> PathBuf {
    residual_dir.join(LOCK_FILE)
}

pub fn acquire(residual_dir: &Path) -> Result<LockGuard> {
    acquire_with_ttl(residual_dir, DEFAULT_TTL)
}

pub fn acquire_with_ttl(residual_dir: &Path, ttl: Duration) -> Result<LockGuard> {
    let path = lock_path(residual_dir);
    if path.exists() {
        if is_expired(residual_dir)? {
            let _ = fs::remove_file(&path);
        } else {
            bail!("session lock held: {}", path.display());
        }
    }
    let now = now_secs();
    let expires = now + ttl.as_secs();
    fs::write(
        &path,
        format!(
            "pid={}\nacquired={}\nexpires={}\n",
            std::process::id(),
            now,
            expires
        ),
    )
    .with_context(|| format!("write lock {}", path.display()))?;
    Ok(LockGuard { path })
}

pub fn release(residual_dir: &Path) -> Result<()> {
    let path = lock_path(residual_dir);
    if path.exists() {
        fs::remove_file(&path).with_context(|| format!("remove lock {}", path.display()))?;
    }
    Ok(())
}

pub fn is_released(residual_dir: &Path) -> bool {
    !lock_path(residual_dir).exists()
}

fn is_expired(residual_dir: &Path) -> Result<bool> {
    let path = lock_path(residual_dir);
    let content = fs::read_to_string(&path)?;
    for line in content.lines() {
        if let Some(rest) = line.strip_prefix("expires=") {
            let expires: u64 = rest.trim().parse().unwrap_or(0);
            return Ok(now_secs() >= expires);
        }
    }
    Ok(true)
}

fn now_secs() -> u64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|d| d.as_secs())
        .unwrap_or(0)
}

/// Test helper: write a lock that is already expired.
#[cfg(test)]
pub fn write_stale_for_test(residual_dir: &Path, _ttl: Duration) -> Result<()> {
    let path = lock_path(residual_dir);
    let past = now_secs().saturating_sub(10);
    fs::write(
        &path,
        format!("pid=0\nacquired={}\nexpires={}\n", past, past),
    )?;
    Ok(())
}

//! Hash snapshot of managed residual files before write.
use anyhow::Result;
use std::collections::BTreeMap;
use std::path::Path;

/// Managed CSV / data files tracked for change detection.
pub const MANAGED_FILES: &[&str] = &[
    "stressors.csv",
    "purposes.csv",
    "attractors.csv",
    "terminology.csv",
    "components.csv",
];

pub type Snapshot = BTreeMap<String, String>;

/// Hash snapshot of managed files present under residual_dir.
pub fn snapshot(residual_dir: &Path) -> Result<Snapshot> {
    let mut out = BTreeMap::new();
    for name in MANAGED_FILES {
        let path = residual_dir.join(name);
        if path.exists() {
            let bytes = std::fs::read(&path)?;
            out.insert((*name).to_string(), hash_bytes(&bytes));
        }
    }
    Ok(out)
}

/// True when current on-disk hashes differ from a prior snapshot.
pub fn drifted(residual_dir: &Path, prior: &Snapshot) -> Result<bool> {
    Ok(&snapshot(residual_dir)? != prior)
}

pub fn hash_bytes(data: &[u8]) -> String {
    // FNV-1a 64-bit hex — deterministic, dep-free
    let mut hash: u64 = 0xcbf29ce484222325;
    for byte in data {
        hash ^= u64::from(*byte);
        hash = hash.wrapping_mul(0x100000001b3);
    }
    format!("{:016x}", hash)
}

