#[cfg(test)]
mod tests {
    use super::*;
    use tempfile::tempdir;

    #[test]
    fn session_hub_acquires_lockfile() {
        let dir = tempdir().unwrap();
        let residual = dir.path().join("residual");
        std::fs::create_dir_all(&residual).unwrap();

        let guard = lock::acquire(&residual).expect("acquire should succeed");
        let lock_path = residual.join(".session.lock");
        assert!(lock_path.exists(), "lockfile should exist while held");
        drop(guard);
        assert!(
            !lock_path.exists() || lock::is_released(&residual),
            "lock should be released after drop"
        );
    }

    #[test]
    fn session_hub_lock_respects_ttl() {
        let dir = tempdir().unwrap();
        let residual = dir.path().join("residual");
        std::fs::create_dir_all(&residual).unwrap();

        lock::write_stale_for_test(&residual, std::time::Duration::from_secs(0)).unwrap();
        let _guard = lock::acquire_with_ttl(&residual, std::time::Duration::from_secs(60))
            .expect("should reclaim expired lock");
        assert!(residual.join(".session.lock").exists());
    }

    #[test]
    fn session_hub_change_detection_hashes_managed_files() {
        let dir = tempdir().unwrap();
        let residual = dir.path().join("residual");
        std::fs::create_dir_all(&residual).unwrap();
        std::fs::write(residual.join("stressors.csv"), "id,description\n").unwrap();
        std::fs::write(residual.join("purposes.csv"), "id,description\n").unwrap();

        let snap1 = change_detection::snapshot(&residual).expect("snapshot");
        assert!(!snap1.is_empty(), "snapshot should include managed files");

        std::fs::write(residual.join("stressors.csv"), "id,description\nS-01,x\n").unwrap();
        let snap2 = change_detection::snapshot(&residual).expect("snapshot");
        assert_ne!(snap1, snap2, "hash should change after write");
    }

    #[test]
    fn session_hub_routes_verify_all_under_lock() {
        let dir = tempdir().unwrap();
        let residual = dir.path().join("residual");
        std::fs::create_dir_all(&residual).unwrap();
        for (name, header) in [
            (
                "stressors.csv",
                "id,description,naive_change,traits,components_affected,attractor_id",
            ),
            (
                "purposes.csv",
                "id,description,feature,traits,components_enabled,attractor_id",
            ),
            (
                "attractors.csv",
                "id,name,valence,description,phase_state",
            ),
            (
                "terminology.csv",
                "term,definition,domain,related_terms",
            ),
        ] {
            std::fs::write(residual.join(name), format!("{}\n", header)).unwrap();
        }
        let cfg = Config {
            residual_dir: residual.clone(),
            ..Config::default()
        };
        verify_all(&cfg).expect("verify_all should succeed on empty data");
        assert!(
            lock::is_released(&residual),
            "lock must be released after verify_all"
        );
    }
}

