//! skill-install + skill-check fused lifecycle module.
use anyhow::{Context, Result};

pub fn install(name: &str, agent: &str, global: bool) -> Result<()> {
    let (content, _version) = crate::skills::find(name)
        .with_context(|| format!("skill '{}' not found", name))?;
    let agent_parsed: crate::skills::install::Agent = agent.parse()?;
    let path = crate::skills::install::install_path(name, &agent_parsed, global)?;
    crate::skills::install::write_skill(&path, content)?;
    println!("Installed '{}' to {}", name, path.display());
    Ok(())
}

pub fn check(name: &str, agent: &str) -> Result<()> {
    let (_content, embedded_version) = crate::skills::find(name)
        .with_context(|| format!("skill '{}' not found", name))?;
    let agent_parsed: crate::skills::install::Agent = agent.parse()?;
    match crate::skills::install::installed_version(name, &agent_parsed, false)? {
        None => {
            println!("'{}' is not installed for agent '{}'.", name, agent);
        }
        Some(installed_ver) => {
            if installed_ver == embedded_version {
                println!("'{}' is up to date (version {}).", name, installed_ver);
            } else {
                println!(
                    "'{}' is outdated: installed version {}, embedded version {}.",
                    name, installed_ver, embedded_version
                );
            }
        }
    }
    Ok(())
}

#[cfg(test)]
mod tests {
    #[test]
    fn skill_lifecycle_finds_known_skill_for_install_path() {
        assert!(crate::skills::find("purpose-walk").is_some());
        let agent: crate::skills::install::Agent = "agnostic".parse().unwrap();
        let path = crate::skills::install::install_path("purpose-walk", &agent, false).unwrap();
        assert!(path.to_string_lossy().contains("purpose-walk"));
    }
}

//! skill-list + skill-show catalog module.
use anyhow::{Context, Result};

pub fn show(name: &str, version_only: bool) -> Result<()> {
    let (content, version) = crate::skills::find(name)
        .with_context(|| format!("skill '{}' not found", name))?;
    if version_only {
        println!("{}", version);
    } else {
