//! Components registry — loads residual/components.csv architecture sets.
use anyhow::{Context, Result};
use serde::{Deserialize, Serialize};
use std::path::Path;

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
pub struct Component {
    pub name: String,
    pub description: String,
    pub status: String,
    pub architecture_set: String,
}

pub fn load(residual_dir: &Path) -> Result<Vec<Component>> {
    let path = residual_dir.join("components.csv");
    if !path.exists() {
        return Ok(vec![]);
    }
    let mut rdr = csv::ReaderBuilder::new()
        .has_headers(true)
        .from_path(&path)
        .with_context(|| format!("read {}", path.display()))?;
    let mut out = Vec::new();
    for record in rdr.deserialize() {
        let c: Component = record?;
        out.push(c);
    }
    Ok(out)
}

pub fn for_set(residual_dir: &Path, architecture_set: &str) -> Result<Vec<Component>> {
    Ok(load(residual_dir)?
        .into_iter()
        .filter(|c| c.architecture_set == architecture_set)
        .collect())
}

pub fn names_for_set(residual_dir: &Path, architecture_set: &str) -> Result<Vec<String>> {
    Ok(for_set(residual_dir, architecture_set)?
        .into_iter()
        .map(|c| c.name)
        .collect())
}

