mod tests {
    use super::*;
    use std::path::PathBuf;

    fn repo_residual() -> PathBuf {
        // tests run with CARGO_MANIFEST_DIR = worktree root
        PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("residual")
    }

    #[test]
    fn components_csv_loads_A_C2_set() {
        let dir = repo_residual();
        let names = names_for_set(&dir, "A-C2").expect("load A-C2");
        let required = [
            "skill-lifecycle",
            "session-hub",
            "verify-traits",
            "terminology",
            "storage-append",
            "change-detection",
            "cli-add",
            "storage-init",
            "skill-catalog",
            "git-hook",
            "tag-scan",
            "verify-links",
            "storage-io",
            "stressor-schema",
            "components-registry",
            "residues-csv",
            "matrix-view",
            "research-study",
            "personas",
            "storage-attractors",
        ];
        for name in required {
            assert!(
                names.iter().any(|n| n == name),
                "A-C2 missing component '{}'; got {:?}",
                name,
                names
            );
        }
        assert!(
            names.iter().any(|n| n == "research-study"),
            "C2 must list research-study distinctly"
        );
        assert!(
            names.iter().any(|n| n == "personas"),
            "C2 must list personas distinctly"
        );
        assert!(
            !names.iter().any(|n| n == "evidence"),
            "C2 must NOT fuse into evidence"
        );
        let comps = for_set(&dir, "A-C2").unwrap();
        assert!(comps.iter().all(|c| c.status == "proposed"));
        assert!(comps.iter().all(|c| c.architecture_set == "A-C2"));
    }

    #[test]
    fn evidence_split_keeps_personas_and_research_modules_separate() {
        // Compile-time / module-path proof: both storage modules are reachable
        // and there is no crate::evidence path in this architecture.
        let dir = tempfile::tempdir().unwrap();
        let residual = dir.path();
        std::fs::create_dir_all(residual.join("personas")).unwrap();
        std::fs::create_dir_all(residual.join("research")).unwrap();

        crate::storage::personas::create(
            residual,
            crate::storage::personas::Persona {
                name: "alex".into(),
                role: "ops".into(),
                concerns: "latency".into(),
                desires: "stability".into(),
                stressor_ids: vec![],
            },
        )
        .unwrap();
        crate::storage::research::save(residual, "notes", "# research notes\n").unwrap();

        let personas = crate::storage::personas::list_names(residual).unwrap();
        assert!(personas.iter().any(|n| n == "alex"));

        let research_path = residual.join("research/notes.md");
        assert!(
            research_path.exists(),
            "research stays in storage::research, not fused evidence"
        );
    }
}

